/// requires an ordered input. An unordered `limit` is permitted only until a
/// later observable boundary imposes its own ordering requirement. `distinct`
/// likewise imposes no logical ordering — an observable ordered distinct result
/// requires an explicit `order` above it, and an ordered input confers none.
///
/// # NULL and three-valued logic
///
/// Predicates evaluate in Kleene three-valued logic (K3): `TRUE`, `FALSE`, or
/// `UNKNOWN`. Any comparison with a NULL operand is `UNKNOWN`. `filter` and a
/// join's `on` keep only rows that evaluate to `TRUE`, never `UNKNOWN`, so
/// `not (x = 1)` does not match rows where `x` is NULL; `is_null` is the only
/// test that matches a NULL. NULLs are distinct under unique indexes.
///
/// # The wire
///
/// A query is a flat map of caller-chosen node ids plus a root selector. Every
/// definition is inline; a node id is a plain reference carrying no sharing,
/// memoisation, or materialisation identity. The graph must be acyclic, every
/// node must be reachable from the root and have exactly one consumer, and
/// dangling or shared references are rejected before binding. Nodes and
/// expressions are closed `oneOf` unions selected by `kind`; unknown fields,
/// fields belonging to another variant, and missing required fields are
/// rejected. Literal values travel as raw JSON scalars (see `Value`) and are
/// typed by the binder from the context each literal meets.
#[derive(Clone, Debug, PartialEq)]
pub enum Expr {
    LiteralExpr(Box<LiteralExpr>),
    ColumnExpr(Box<ColumnExpr>),
    UnaryExpr(Box<UnaryExpr>),
    BinaryExpr(Box<BinaryExpr>),
    CastExpr(Box<CastExpr>),
    BranchExpr(Box<BranchExpr>),
    TextMatchExpr(Box<TextMatchExpr>),
    CrossingExprExists(Box<CrossingExprExists>),
    CrossingExprFirst(Box<CrossingExprFirst>),
    CrossingExprScalar(Box<CrossingExprScalar>),
    CrossingExprArray(Box<CrossingExprArray>),
}

impl Serialize for Expr {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::LiteralExpr(value) => LiteralExprWireRef {
                kind: LiteralExprTag::Value,
                value: &value.value,
            }
            .serialize(serializer),
            Self::ColumnExpr(value) => ColumnExprWireRef {
                kind: ColumnExprTag::Value,
                column: &value.column,
                scope: &value.scope,
            }
            .serialize(serializer),
            Self::UnaryExpr(value) => UnaryExprWireRef {
                kind: UnaryExprTag::Value,
                expr: &value.expr,
                op: &value.op,
            }
            .serialize(serializer),
            Self::BinaryExpr(value) => BinaryExprWireRef {
                kind: BinaryExprTag::Value,
                left: &value.left,
                op: &value.op,
                right: &value.right,
            }
            .serialize(serializer),
            Self::CastExpr(value) => CastExprWireRef {
                kind: CastExprTag::Value,
                expr: &value.expr,
                to: &value.to,
            }
            .serialize(serializer),
            Self::BranchExpr(value) => BranchExprWireRef {
                kind: BranchExprTag::Value,
                branches: &value.branches,
                r#else: &value.r#else,
            }
            .serialize(serializer),
            Self::TextMatchExpr(value) => TextMatchExprWireRef {
                kind: TextMatchExprTag::Value,
                comparison: &value.comparison,
                parts: &value.parts,
                value: &value.value,
            }
            .serialize(serializer),
            Self::CrossingExprExists(value) => CrossingExprExistsWireRef {
                kind: CrossingExprExistsTag::Value,
                node: &value.node,
            }
            .serialize(serializer),
            Self::CrossingExprFirst(value) => CrossingExprFirstWireRef {
                kind: CrossingExprFirstTag::Value,
                node: &value.node,
            }
            .serialize(serializer),
            Self::CrossingExprScalar(value) => CrossingExprScalarWireRef {
                kind: CrossingExprScalarTag::Value,
                node: &value.node,
            }
            .serialize(serializer),
            Self::CrossingExprArray(value) => CrossingExprArrayWireRef {
                kind: CrossingExprArrayTag::Value,
                node: &value.node,
            }
            .serialize(serializer),
        }
    }
}

impl<'de> Deserialize<'de> for Expr {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        struct Discriminator {
            #[serde(rename = "kind")]
            value: String,
        }

        let raw = Box::<RawValue>::deserialize(deserializer)?;
        let discriminator: Discriminator =
            serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
        match discriminator.value.as_str() {
            "lit" => {
                let wire: LiteralExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::LiteralExpr(Box::new(LiteralExpr {
                    value: wire.value,
                })))
            }
            "col" => {
                let wire: ColumnExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::ColumnExpr(Box::new(ColumnExpr {
                    column: wire.column,
                    scope: wire.scope,
                })))
            }
            "unary" => {
                let wire: UnaryExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::UnaryExpr(Box::new(UnaryExpr {
                    expr: wire.expr,
                    op: wire.op,
                })))
            }
            "binary" => {
                let wire: BinaryExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::BinaryExpr(Box::new(BinaryExpr {
                    left: wire.left,
                    op: wire.op,
                    right: wire.right,
                })))
            }
            "cast" => {
                let wire: CastExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::CastExpr(Box::new(CastExpr {
                    expr: wire.expr,
                    to: wire.to,
                })))
            }
            "branch" => {
                let wire: BranchExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::BranchExpr(Box::new(BranchExpr {
                    branches: wire.branches,
                    r#else: wire.r#else,
                })))
            }
            "text_match" => {
                let wire: TextMatchExprWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::TextMatchExpr(Box::new(TextMatchExpr {
                    comparison: wire.comparison,
                    parts: wire.parts,
                    value: wire.value,
                })))
            }
            "exists" => {
                let wire: CrossingExprExistsWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::CrossingExprExists(Box::new(CrossingExprExists {
                    node: wire.node,
                })))
            }
            "first" => {
                let wire: CrossingExprFirstWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::CrossingExprFirst(Box::new(CrossingExprFirst {
                    node: wire.node,
                })))
            }
            "scalar" => {
                let wire: CrossingExprScalarWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::CrossingExprScalar(Box::new(CrossingExprScalar {
                    node: wire.node,
                })))
            }
            "array" => {
                let wire: CrossingExprArrayWire =
                    serde_json::from_str(raw.get()).map_err(serde::de::Error::custom)?;
                Ok(Self::CrossingExprArray(Box::new(CrossingExprArray {
                    node: wire.node,
                })))
            }
            value => Err(serde::de::Error::custom(format!(
                "Expr: unknown kind {value:?}"
            ))),
        }
    }
}

/// A constant value. `value` is a scalar wire value (see `Value`); numeric
/// values travel as lossless strings, so a 64-bit integer keeps full
/// precision on the wire.
#[derive(Clone, Debug, PartialEq)]
