/// Ordered, lazy branching. Evaluate branch predicates in document order.
/// The result is the `then` expression belonging to the first predicate
/// that evaluates to TRUE. Predicates evaluating to FALSE or UNKNOWN do
/// not match. If none match, evaluate and return `else`. Unselected result
/// expressions are not evaluated — the laziness is contract, not
/// optimization: a division by zero in an arm that is never selected does
/// not raise.
///
/// `else` is required. LIR has typed NULLs only, so there is no
/// implicit-NULL default; a frontend that permits an omitted else inserts
/// a correctly typed NULL itself.
///
/// Typing: every `when` must be boolean (nullable is fine — an UNKNOWN
/// predicate falls through). Every `then` and the `else` must have the
/// same scalar kind, with no implicit widening; a frontend inserts
/// explicit casts. The result is that kind, nullable when any `then` or
/// the `else` is. A branch subtree may not contain a crossing (`exists` /
/// `first` / `scalar` / `array`) anywhere — in a `when`, a `then`, or the
/// `else`: the executor attaches crossings per row before expression
/// evaluation, which would evaluate crossings in never-selected arms, so
/// they are rejected at bind time.
#[derive(Clone, Debug, PartialEq)]
pub struct BranchExpr {
    /// The arms, tested in document order.
    pub branches: Vec<BranchArm>,
    /// The result when no predicate matches.
    pub r#else: Expr,
}

#[derive(Clone, Copy, Serialize, Deserialize)]
enum BranchExprTag {
    #[serde(rename = "branch")]
    Value,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct BranchExprWire {
    #[serde(rename = "kind")]
    _kind: BranchExprTag,
    #[serde(rename = "branches")]
    branches: Vec<BranchArm>,
    #[serde(rename = "else")]
    r#else: Expr,
}

#[derive(Serialize)]
struct BranchExprWireRef<'a> {
    #[serde(rename = "kind")]
    kind: BranchExprTag,
    #[serde(rename = "branches")]
    branches: &'a Vec<BranchArm>,
    #[serde(rename = "else")]
    r#else: &'a Expr,
}

/// Test whether `value` matches an anchored pattern built from an ordered
/// list of `parts`. The result is boolean under three-valued logic: a NULL
/// `value` yields UNKNOWN, otherwise a total TRUE or FALSE. `value` must be
/// text.
///
/// The match is fully anchored: the concatenation of the parts must consume
/// the whole of `value`, not merely occur within it. `[literal "foo"]`
/// matches only "foo"; a leading or trailing `any_many` is what admits a
/// prefix, suffix, or infix. An `any_many` matches zero or more characters
/// (SQL `%`), so `[any_many]` alone matches every non-NULL value including
/// the empty string.
///
/// The pattern is a bind-time constant: literal spans carry strings and
/// wildcards are structural, so no part is an expression and the matcher is
/// compiled once. `value` is the only operand that varies per row, and NULL
/// enters only through it.
///
/// `comparison` controls only how literal spans compare with corresponding
/// input text. `exact`, the default, requires identical UTF-8 bytes.
/// `unicode_simple_fold` interprets both spans as UTF-8 and compares their
/// Unicode code points under Unicode simple case folding, with the same
/// equality relation as Go's `strings.EqualFold`. Simple folding is
/// one-code-point-to-one-code-point, deterministic, and locale-independent.
/// It performs no Unicode normalization, accent folding, transliteration,
/// multi-code-point full folding, or linguistic collation. In particular,
/// "Straße" does not match "STRASSE", "é" does not match "e", and composed
/// and decomposed forms remain distinct.
///
/// This setting is deliberately narrower than a database collation. A
/// future cross-cutting collation design may govern equality, ordering,
/// grouping, uniqueness, and matching together; `unicode_simple_fold`
/// remains the precisely defined compatibility comparison provided by this
/// expression.
///
/// This is deliberately the SQL `LIKE` wildcard set structurally
/// represented, not a general pattern algebra: no alternation, repetition of
/// sub-patterns, character classes, or backreferences. A richer text-search
/// facility would be a separate expression, never a wider `parts`
/// vocabulary.
#[derive(Clone, Debug, PartialEq)]
pub struct TextMatchExpr {
    /// How literal pattern spans compare with input text. Omission is
    /// equivalent to `exact`.
    pub comparison: OptionalField<TextComparison>,
    /// The pattern, as an ordered list of literal spans and wildcards.
    /// Producers should emit a canonical list — adjacent literals coalesced,
    /// adjacent `any_many` collapsed — but the matcher accepts any
    /// well-formed list.
    pub parts: Vec<TextMatchExprPart>,
    /// The text expression matched against the pattern.
    pub value: Expr,
}

#[derive(Clone, Copy, Serialize, Deserialize)]
enum TextMatchExprTag {
    #[serde(rename = "text_match")]
    Value,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct TextMatchExprWire {
    #[serde(rename = "kind")]
    _kind: TextMatchExprTag,
    #[serde(rename = "comparison", default)]
    comparison: OptionalField<TextComparison>,
    #[serde(rename = "parts")]
    parts: Vec<TextMatchExprPart>,
    #[serde(rename = "value")]
    value: Expr,
}

#[derive(Serialize)]
struct TextMatchExprWireRef<'a> {
    #[serde(rename = "kind")]
    kind: TextMatchExprTag,
    #[serde(
        rename = "comparison",
        skip_serializing_if = "OptionalField::is_missing"
    )]
    comparison: &'a OptionalField<TextComparison>,
    #[serde(rename = "parts")]
    parts: &'a Vec<TextMatchExprPart>,
    #[serde(rename = "value")]
    value: &'a Expr,
}

